rule CobaltStrike_Beacon_Generic {
    meta:
        description = "Detects generic Cobalt Strike beacon patterns"
        author = "SOC Team"
        reference = "https://attack.mitre.org/software/S0154/"
        date = "2026-04-11"
    strings:
        $x64_beacon = { 60 E8 00 00 00 00 58 83 C0 06 83 EC 70 C7 44 24 }
        $useragent = "Mozilla/5.0 (Windows NT" wide ascii
        $cfg_junk = { 00 00 00 00 00 00 00 00 00 00 }
    condition:
        all of them
}

